-- خدمات
INSERT OR IGNORE INTO services (id, category_id, title, slug, short_desc, description, price, delivery_days, image_url, status) VALUES
  (1, 1, 'تصميم شعار (لوجو) احترافي', 'logo-design', 'تصميم شعار مميز لعلامتك التجارية', 'نقوم بتصميم شعار احترافي وفريد يعكس هوية علامتك التجارية مع 3 مفاهيم مختلفة وتعديلات غير محدودة حتى الرضا التام.', 150, 3, 'https://images.unsplash.com/photo-1626785774573-4b799315345d?w=600', 'active'),
  (2, 1, 'تصميم هوية بصرية كاملة', 'brand-identity', 'شعار + بطاقات + قوالب سوشيال ميديا', 'حزمة هوية بصرية متكاملة تشمل الشعار، الألوان، الخطوط، بطاقة أعمال، وقوالب لمنصات التواصل الاجتماعي.', 450, 7, 'https://images.unsplash.com/photo-1561070791-2526d30994b5?w=600', 'active'),
  (3, 2, 'تطوير موقع ويب تعريفي', 'business-website', 'موقع تعريفي متجاوب لشركتك', 'تصميم وبرمجة موقع تعريفي عصري ومتجاوب مع جميع الأجهزة، يشمل صفحة رئيسية وصفحات فرعية حسب الحاجة.', 800, 10, 'https://images.unsplash.com/photo-1547658719-da2b51169166?w=600', 'active'),
  (4, 2, 'تطوير متجر إلكتروني', 'ecommerce-store', 'متجر متكامل مع نظام دفع', 'إنشاء متجر إلكتروني متكامل مع سلة شراء، بوابة دفع، ولوحة تحكم لإدارة المنتجات والطلبات.', 2000, 21, 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=600', 'active'),
  (5, 3, 'إدارة حسابات التواصل الاجتماعي', 'social-media-management', 'إدارة شهرية لحساباتك', 'إدارة كاملة لحسابات التواصل الاجتماعي تشمل التخطيط، التصميم، النشر، والتفاعل مع المتابعين لمدة شهر كامل.', 350, 30, 'https://images.unsplash.com/photo-1611162617213-7d7a39e9b1d7?w=600', 'active'),
  (6, 3, 'حملة إعلانية على منصات التواصل', 'social-ads-campaign', 'حملة ممولة تستهدف جمهورك', 'إعداد وإدارة حملة إعلانية ممولة على فيسبوك/انستقرام تستهدف الجمهور المناسب لزيادة المبيعات والتفاعل.', 300, 14, 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600', 'active'),
  (7, 4, 'كتابة محتوى تسويقي', 'content-writing', 'محتوى جذاب يحول الزوار لعملاء', 'كتابة محتوى تسويقي احترافي (مقالات، أوصاف منتجات، محتوى مواقع) بأسلوب جذاب ومحسن لمحركات البحث.', 100, 3, 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=600', 'active'),
  (8, 4, 'ترجمة معتمدة (عربي-إنجليزي)', 'translation-service', 'ترجمة دقيقة واحترافية', 'خدمة ترجمة دقيقة من العربية للإنجليزية وبالعكس للمستندات، المقالات، والمواقع بجودة عالية.', 80, 2, 'https://images.unsplash.com/photo-1546410531-bb4caa6b424d?w=600', 'active');

-- طرق دفع يدوية
INSERT OR IGNORE INTO payment_methods (id, name, type, account_info, instructions, is_active, sort_order) VALUES
  (1, 'تحويل بنكي', 'bank_transfer', 'اسم البنك: البنك الأهلي | رقم الحساب: 1234567890 | اسم المستفيد: منصة الخدمات', 'قم بتحويل المبلغ إلى الحساب البنكي أعلاه، ثم قم برفع صورة إيصال التحويل هنا مع كتابة رقم العملية إن وجد.', 1, 1),
  (2, 'محفظة إلكترونية (STC Pay)', 'wallet', 'رقم المحفظة: 0555555555 | الاسم: منصة الخدمات', 'قم بتحويل المبلغ عبر تطبيق STC Pay إلى الرقم أعلاه، ثم قم برفع صورة تأكيد العملية.', 1, 2);

